args:
$env:PSModulePath = "$PSHOME\Modules;$env:PSModulePath"
$output = @()
try {
    $output = @(& scripts/smoke-windows.ps1 -UpstreamWaitSeconds 300 2>&1)
    $code = $LASTEXITCODE
} catch {
    $output += $_
    $code = 1
}
$output | ForEach-Object { [string]$_ } | Where-Object { $_ -match '^(listeners:|\[frida\] attached|action-required=|upstream-peer-validated=|agent-on-load-start=|live-cdp-matrix:|link-smoke:|renderer-selection=|fallback-applet-renderer=|reused-applet-renderer=|child-exit-status=|child-exit-code=|target-survives-shutdown=|target-process-delta:|ports-released=|force-termination=)' }
exit $code
